// Paperless-ngx API endpoints - ALL paths must end with /
const endpoints = [
  {
    "endpoint": "/api/documents/",
    "method": "GET",
    "description": "List all documents. Optional params: ?query=searchterm. Returns array of documents."
  },
  {
    "endpoint": "/api/documents/",
    "method": "POST",
    "description": "Create a new document. Body: {title, content, tags, correspondent, document_type}. File upload requires separate handling."
  },
  {
    "endpoint": "/api/documents/{id}/",
    "method": "GET",
    "description": "Get details of document by ID. Replace {id} with actual document ID."
  },
  {
    "endpoint": "/api/documents/{id}/",
    "method": "PATCH",
    "description": "Update document by ID. Body: fields to update. Replace {id} with actual document ID."
  },
  {
    "endpoint": "/api/documents/{id}/",
    "method": "DELETE",
    "description": "Delete document by ID. Replace {id} with actual document ID."
  },
  {
    "endpoint": "/api/tags/",
    "method": "GET",
    "description": "List all tags. Returns array of tags."
  },
  {
    "endpoint": "/api/tags/",
    "method": "POST",
    "description": "Create a new tag. Body: {name, color, is_inbox_tag}."
  },
  {
    "endpoint": "/api/tags/{id}/",
    "method": "GET",
    "description": "Get tag details by ID. Replace {id} with actual tag ID."
  },
  {
    "endpoint": "/api/tags/{id}/",
    "method": "PATCH",
    "description": "Update tag by ID. Body: fields to update. Replace {id} with actual tag ID."
  },
  {
    "endpoint": "/api/tags/{id}/",
    "method": "DELETE",
    "description": "Delete tag by ID. Replace {id} with actual tag ID."
  },
  {
    "endpoint": "/api/correspondents/",
    "method": "GET",
    "description": "List all correspondents."
  },
  {
    "endpoint": "/api/document_types/",
    "method": "GET",
    "description": "List all document types."
  }
];

// Search query from AI agent
const searchQuery = query.toLowerCase();

// Search through endpoints
const matches = endpoints.filter(ep => {
  const searchText = `${ep.endpoint} ${ep.method} ${ep.description}`.toLowerCase();
  return searchText.includes(searchQuery);
});

if (matches.length === 0) {
  return `No matching endpoints for: "${query}". Available: documents (list/create/get/update/delete), tags (list/create/get/update/delete), correspondents, document_types.`;
}

// Return formatted results
return matches.map(ep => 
  `Endpoint: ${ep.endpoint}\nMethod: ${ep.method}\nDescription: ${ep.description}\n⚠️ IMPORTANT: URL must end with trailing slash!`
).join('\n\n---\n\n');
